local Players = game:GetService("Players")
local Stats = game:GetService("Stats")
local TweenService = game:GetService("TweenService")

local Sensation = __require("Sensation")
local Library = __require("Library")
local Task = __require("Task")
local ColorPicker = __require("ColorPicker")
local OSDetector = __require("OSDetector")

local Dragify = Library.Dragify
local Blurify = Library.Blurify
local Buttonify = Library.Buttonify
local Scrollify = Library.Scrollify
local Searchify = Library.Searchify
local Visualify = Library.Visualify

local LocalPlayer = Players.LocalPlayer
local Mode = "Standard"

local function noop() end

local Window = Sensation:CreateWindow()
Dragify(Window.Frame)
Blurify(Window.Frame)

local Theme = Library.Themeify(Window.Gradients)
Theme.UIGradients = Window.Gradients
Theme.Index = 0

local function notify(message)
	local n = Window:CreateNotification({ Message = message })
	Blurify(n.Frame)
	TweenService:Create(n, TweenInfo.new(0.75, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		Size = UDim2.new(1, 10, 0, 90),
	}):Play()
	Task.Delay(2, function()
		TweenService:Create(n, TweenInfo.new(0.75, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
			Size = UDim2.new(0.5, 0, 0, 90),
		}):Play()
		Task.Delay(1, game.Destroy, n)
	end)
end

Window:AddQuickButton({ Name = "Respawn", Image = "rbxassetid://11293978505", Callback = noop })
Window:AddQuickButton({ Name = "Rig", Image = "rbxassetid://11295273292", Callback = noop })

local Tabs = {}
Tabs.Executor = Window:AddTab({ Name = "Executor", Image = "rbxassetid://11422141395" })
Tabs.Home = Window:AddTab({ Name = "Home", Image = "rbxassetid://11433532654" })
Tabs.Hub = Window:AddTab({ Name = "Hub", Image = "rbxassetid://11419703033" })
Tabs.Logs = Window:AddTab({ Name = "Logs", Image = "rbxassetid://11422154787" })
Tabs.Music = Window:AddTab({ Name = "Music", Image = "rbxassetid://11432850205" })
Tabs.Players = Window:AddTab({ Name = "Players", Image = "rbxassetid://11432832657" })
Tabs.Settings = Window:AddTab({ Name = "Settings", Image = "rbxassetid://11293977610" })

local TOP = {
	ScrollingEnabled = true,
	AutomaticSize = Enum.AutomaticSize.X,
	Size = UDim2.new(1, 0, 0, 40),
	ScrollingDirection = Enum.ScrollingDirection.X,
	FillDirection = Enum.FillDirection.Horizontal,
}
local MIDDLE = {
	ScrollingEnabled = true,
	AutomaticSize = Enum.AutomaticSize.Y,
	Size = UDim2.new(1, 0, 1, -120),
	ScrollingDirection = Enum.ScrollingDirection.Y,
	FillDirection = Enum.FillDirection.Vertical,
}

local function rowConfig()
	return table.clone(TOP)
end
local function listConfig()
	return table.clone(MIDDLE)
end

local BUTTON_FX = {
	EnableMask = true,
	Color = Color3.new(1, 1, 1),
	Offset = Vector2.zero,
	Lifetime = 0.5,
	Scale = 250,
	RippleAlpha = 0.5,
	SelectionAlpha = 0.9,
	ThemeObject = Theme,
}

do
	local top = Tabs.Executor:AddFrame(rowConfig())
	local code = Tabs.Executor:AddCodeFrame({
		ScrollingEnabled = true,
		AutomaticSize = Enum.AutomaticSize.XY,
		Size = UDim2.new(1, 0, 1, -120),
		ScrollingDirection = Enum.ScrollingDirection.XY,
		FillDirection = Enum.FillDirection.Vertical,
	})
	local bottom = Tabs.Executor:AddFrame(rowConfig())
	Scrollify(top.Frame)
	Scrollify(bottom.Frame)

	local count = 0
	local sources = {}
	local plus
	local current = 1

	local function onAddTab()
		count += 1
		if plus then
			plus:Destroy()
		end
		local index = count
		local tab = top:AddEnum({ Name = "Script " .. count })
		plus = top:AddSmallButton({ Name = "+" })
		plus.MouseButton1Click:Once(onAddTab)
		sources[count] = 'print("Hello World")'
		tab.MouseButton1Click:Connect(function()
			sources[current] = code:GetText()
			current = index
			code:SetText(sources[current])
		end)
		if count == 1 then
			TweenService:Create(tab.TextLabel, Window.TweenInfo, { TextTransparency = 0 }):Play()
			TweenService:Create(tab.Frame, Window.TweenInfo, { BackgroundTransparency = 0.5 }):Play()
			TweenService:Create(tab.Frame.ImageLabel, Window.TweenInfo, { ImageTransparency = 0.5 }):Play()
			top.Config.Selected = tab
			code:SetText(sources[current])
		end
	end
	onAddTab()

	local execute = bottom:AddSmallButton({ Name = "Execute" })
	execute.MouseButton1Click:Connect(noop)

	local clear = bottom:AddSmallButton({ Name = "Clear" })
	clear.MouseButton1Click:Connect(function()
		code:SetText("")
	end)

	local hideConfig = { Name = "Hide", Enabled = false }
	local hide = bottom:AddToggle(hideConfig)
	Task.Spawn(function()
		local target
		while not target do
			task.wait()
			for _, child in (code.Frame):GetDescendants() do
				if child:IsA("Frame") and child.Size == UDim2.new(1, -40, 1, 0) then
					target = child
					break
				end
			end
		end
		hide.MouseButton1Click:Connect(function()
			target.Visible = not hideConfig.Enabled
		end)
	end)
end

do
	local top = Tabs.Home:AddFrame(rowConfig())
	local list = Tabs.Home:AddFrame(listConfig())
	local bottom = Tabs.Home:AddFrame(rowConfig())
	Scrollify(top.Frame)
	Scrollify(list.Frame)
