do
	local top = Tabs.Settings:AddFrame(rowConfig())
	local list = Tabs.Settings:AddFrame(listConfig())
	Tabs.Settings:AddFrame(rowConfig())

	local mainPicker = ColorPicker.new()
	local subPicker = ColorPicker.new()
	local mainSwatch, subSwatch

	mainPicker:SetColor(Theme.Themes[0].Keypoints[1].Value)
	subPicker:SetColor(Theme.Themes[0].Keypoints[2].Value)

	local function onColorChanged()
		Theme.Themes[0] = ColorSequence.new(mainPicker:GetColor(), subPicker:GetColor())
		if mainSwatch then
			mainSwatch.BackgroundColor3 = mainPicker:GetColor()
		end
		if subSwatch then
			subSwatch.BackgroundColor3 = subPicker:GetColor()
		end
	end
	mainPicker.Changed:Connect(onColorChanged)
	subPicker.Changed:Connect(onColorChanged)

	local function swatch(parent, color)
		local frame = Instance.new("Frame")
		frame.AnchorPoint = Vector2.new(1, 0.5)
		frame.Position = UDim2.new(1, -10, 0.5, 0)
		frame.Size = UDim2.fromOffset(20, 20)
		frame.BackgroundColor3 = color
		frame.BackgroundTransparency = 0.5
		frame.Parent = parent
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, 10)
		corner.Parent = frame
		return frame
	end

	local function tag(parent, text, color)
		local label = Instance.new("TextLabel")
		label.Text = tostring(text)
		label.AnchorPoint = Vector2.new(1, 0.5)
		label.Position = UDim2.new(1, -10, 0.5, 0)
		label.Size = UDim2.fromOffset(20, 20)
		label.BackgroundTransparency = 1
		label.TextColor3 = color
		label.Parent = parent
		return label
	end

	top:AddEnum({ Name = "Hud" }).MouseButton1Click:Connect(function()
		list:ClearAllChildren()

		local main = list:AddButton({ Name = "Main Theme" })
		Buttonify(main)
		main.MouseButton1Click:Connect(function()
			mainPicker:Start()
			subPicker:Cancel()
		end)
		mainSwatch = swatch(main, mainPicker:GetColor())

		local sub = list:AddButton({ Name = "Sub Theme" })
		Buttonify(sub)
		sub.MouseButton1Click:Connect(function()
			subPicker:Start()
			mainPicker:Cancel()
		end)
		subSwatch = swatch(sub, subPicker:GetColor())

		local indexButton = list:AddButton({ Name = "Theme Index" })
		Buttonify(indexButton)
		local indexLabel = tag(indexButton, Theme.Index, Color3.fromRGB(242, 186, 42))
		indexButton.MouseButton1Click:Connect(function()
			local value = (Theme.Index + 1) % (#Theme.Themes + 1)
			Theme.Index = value
			indexLabel.Text = value
		end)
		indexButton.MouseButton2Click:Connect(function()
			local value = (Theme.Index - 1) % (#Theme.Themes + 1)
			Theme.Index = value
			indexLabel.Text = value
		end)

		local converter = list:AddButton({ Name = "Converter" })
		Buttonify(converter)
		tag(converter, "true", Color3.fromRGB(242, 186, 42))
		converter.MouseButton1Click:Connect(noop)

		local blur = list:AddButton({ Name = "Blur" })
		Buttonify(blur)
		tag(blur, "true", Color3.fromRGB(242, 186, 42))
		blur.MouseButton1Click:Connect(noop)

		local context = list:AddButton({ Name = "Sound Context" })
		Buttonify(context)
		tag(context, "Client", Color3.fromRGB(97, 161, 241))
		context.MouseButton1Click:Connect(noop)
	end)

	top:AddEnum({ Name = "Utility" }).MouseButton1Click:Connect(function()
		list:ClearAllChildren()
		for _, name in { "R6 Dummy", "R15 Dummy", "Reset Mouse", "Reset Camera", "Save Map", "Load Map", "New Server" } do
			local button = list:AddButton({ Name = name })
			Buttonify(button)
			button.MouseButton1Click:Connect(noop)
		end
	end)
end

do
	local concat = table.concat
	local pack = table.pack

	local function hex()
		return Theme.ColorSequence.Keypoints[1].Value:ToHex()
	end

	local function widget(name, getValue)
		local w = Window:AddWidget({ Name = name })
		Dragify(w.Frame)
		Blurify(w.Frame)
		w.Label.Text = ('<font transparency="0">%s:</font> 0'):format(name)
		Task.Spawn(function()
			while true do
				task.wait()
				if not w.Enabled then
					continue
				end
				w.Label.Text = concat(pack(
					'<font color="#', hex(), '"><font transparency="0">', name, ':</font></font> ',
					tostring(getValue())
				))
			end
		end)
		return w
	end

	local platform = OSDetector.detect(LocalPlayer)

	widget("Edition", function()
		return Mode
	end)
	widget("Platform", function()
		return platform.Name
	end)
	widget("Authority", function()
		return Enum.AuthorityMode.Automatic.Name
	end)
	widget("Heap", function()
		return math.floor(gcinfo())
	end)
	widget("Ping", function()
		return math.floor(LocalPlayer:GetNetworkPing() * 1000)
	end)
	widget("Memory", function()
		if Stats.MemoryTrackingEnabled then
			return math.floor(Stats:GetTotalMemoryUsageMb())
		end
		return 0
	end)
	widget("Frames", function()
		return math.floor(1 / Stats.FrameTime)
	end)
	widget("Speed", function()
		local character = LocalPlayer.Character
		local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
		local root = humanoid and humanoid.RootPart
		if not root then
			return 0
		end
		local v = root.AssemblyLinearVelocity
		return math.floor(math.sqrt(v.X ^ 2 + v.Z ^ 2))
	end)
	widget("X", function()
		local character = LocalPlayer.Character
		return character and math.floor(character:GetPivot().Position.X) or "NaN"
	end)
	widget("Y", function()
		local character = LocalPlayer.Character
		return character and math.floor(character:GetPivot().Position.Y) or "NaN"
	end)
	widget("Z", function()
		local character = LocalPlayer.Character
		return character and math.floor(character:GetPivot().Position.Z) or "NaN"
	end)
end

